# retain original outer frame at rows/cols 1 and 25, spanning coordinates 1..25
for r in range(1,26):
    for c in range(1,26):
        if r in (1,25) or c in (1,25): g[r][c]=5
# fill concentric rings in the 23x23 interior, alternating 2 and 5, leaving 3x3 center blank
for k in range(10):
    color=2 if k%2==0 else 5
    lo=2+k; hi=24-k
    for c in range(lo,hi+1):
        g[lo][c]=color; g[hi][c]=color
    for r in range(lo,hi+1):
        g[r][lo]=color; g[r][hi]=color
print(__import__('json').dumps(g,separators=(',',':')))

